

import typing

import pydantic
from ..core.pydantic_utilities import IS_PYDANTIC_V2, UniversalBaseModel
from .compact_resource_usage_input_tokens_details import CompactResourceUsageInputTokensDetails
from .compact_resource_usage_output_tokens_details import CompactResourceUsageOutputTokensDetails


class CompactResourceUsage(UniversalBaseModel):
    """
    Token accounting for the compaction pass, including cached, reasoning, and total tokens.
    """

    input_tokens: int = pydantic.Field()
    """
    The number of input tokens that were used to generate the response.
    """

    output_tokens: int = pydantic.Field()
    """
    The number of output tokens that were generated by the model.
    """

    total_tokens: int = pydantic.Field()
    """
    The total number of tokens that were used.
    """

    input_tokens_details: CompactResourceUsageInputTokensDetails = pydantic.Field()
    """
    A breakdown of input token usage that was recorded.
    """

    output_tokens_details: CompactResourceUsageOutputTokensDetails = pydantic.Field()
    """
    A breakdown of output token usage that was recorded.
    """

    if IS_PYDANTIC_V2:
        model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(extra="allow", frozen=True)
    else:

        class Config:
            frozen = True
            smart_union = True
            extra = pydantic.Extra.allow
